import React, { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import {
  Box, Typography, Chip, Divider,
  IconButton, AppBar, Toolbar, Button, Avatar,
  Snackbar, Alert, Tooltip
} from "@mui/material";
import FavoriteIcon from "@mui/icons-material/Favorite";
import FavoriteBorderIcon from "@mui/icons-material/FavoriteBorder";
import ShareIcon from "@mui/icons-material/Share";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { red } from "@mui/material/colors";

export default function ProductDetail() {
  const { state } = useLocation();
  const navigate = useNavigate();
  const product = state?.product;

  const [liked, setLiked] = useState(false);
  const [likeCount, setLikeCount] = useState(0);
  const [snackbar, setSnackbar] = useState({ open: false, message: "", severity: "success" });

  // ❤️ Toggle like
  const handleLike = () => {
    if (liked) {
      setLiked(false);
      setLikeCount((prev) => prev - 1);
      setSnackbar({ open: true, message: "Removed from wishlist", severity: "info" });
    } else {
      setLiked(true);
      setLikeCount((prev) => prev + 1);
      setSnackbar({ open: true, message: "Added to wishlist ❤️", severity: "success" });
    }
  };

  // 📤 Share
  const handleShare = async () => {
    const shareUrl = window.location.href;
    const shareText = `Check out this product: ${product?.name} at ₹${product?.price}`;

    if (navigator.share) {
      try {
        await navigator.share({
          title: product?.name,
          text: shareText,
          url: shareUrl,
        });
        setSnackbar({ open: true, message: "Shared successfully!", severity: "success" });
      } catch (error) {
        // user cancelled — do nothing
        console.log(error)
      }
    } else {
      try {
        await navigator.clipboard.writeText(shareUrl);
        setSnackbar({ open: true, message: "Link copied to clipboard! 📋", severity: "success" });
      } catch (error) {
        setSnackbar({ open: true, message: "Could not copy link", severity: "error" });
        console.log(error)
      }
    }
  };

  const handleSnackbarClose = () => setSnackbar({ ...snackbar, open: false });

  if (!product) {
    return (
      <Box sx={{ p: 4, textAlign: "center" }}>
        <Typography variant="h5">Product not found.</Typography>
        <Button onClick={() => navigate(-1)} sx={{ mt: 2 }}>Go Back</Button>
      </Box>
    );
  }

  return (
    <Box sx={{ minHeight: "100vh", bgcolor: "#f5f5f5" }}>

      {/* Top Bar */}
      <AppBar position="static" sx={{ bgcolor: "#1976d2" }}>
        <Toolbar>
          <IconButton edge="start" color="inherit" onClick={() => navigate(-1)} sx={{ mr: 2 }}>
            <ArrowBackIcon />
          </IconButton>
          <Typography variant="h6" sx={{ flexGrow: 1 }}>Product Details</Typography>
        </Toolbar>
      </AppBar>

      {/* Content Box */}
      <Box
        sx={{
          maxWidth: 900,
          mx: "auto",
          mt: 4,
          mb: 6,
          px: 2,
          display: "flex",
          flexDirection: { xs: "column", md: "row" },
          bgcolor: "#fff",
          borderRadius: 3,
          boxShadow: "0 4px 24px rgba(0,0,0,0.10)",
          overflow: "hidden",
        }}
      >
        {/* LEFT — Product Image */}
        <Box sx={{
          flex: "0 0 400px",
          bgcolor: "#f0f4f8",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          p: 4,
          minHeight: 400,
        }}>
          <Box
            component="img"
            src={`http://localhost:7000/image/${product?.productimage}`}
            alt={product?.name}
            onError={(e) => {
              e.target.src = "https://via.placeholder.com/300x300?text=No+Image";
            }}
            sx={{
              width: "100%",
              maxWidth: 340,
              maxHeight: 360,
              objectFit: "contain",
              borderRadius: 2,
              boxShadow: "0 8px 32px rgba(0,0,0,0.12)",
              transition: "transform 0.3s",
              "&:hover": { transform: "scale(1.04)" },
            }}
          />
        </Box>

        {/* RIGHT — Product Info */}
        <Box sx={{ flex: 1, p: 4, display: "flex", flexDirection: "column" }}>

          <Box sx={{ display: "flex", alignItems: "center", gap: 1.5, mb: 2 }}>
            <Avatar sx={{ bgcolor: red[500], fontWeight: 700 }}>
              {product?.name?.charAt(0)}
            </Avatar>
            {product?.categoryId?.categoryName && (
              <Chip label={product.categoryId.categoryName} size="small" color="primary" />
            )}
          </Box>

          <Typography variant="h4" fontWeight={700} sx={{ mb: 1, color: "#1a1a2e" }}>
            {product?.name}
          </Typography>

          <Typography variant="h5" sx={{ color: "#1976d2", fontWeight: 600, mb: 2 }}>
            ₹{Number(product?.price).toLocaleString("en-IN")}
          </Typography>

          <Divider sx={{ mb: 2 }} />

          <Typography variant="subtitle1" fontWeight={600} sx={{ mb: 1 }}>
            Description
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2, lineHeight: 1.8 }}>
            {product?.description}
          </Typography>

          <Divider sx={{ mb: 2 }} />

          <Box sx={{ display: "flex", flexDirection: "column", gap: 0.8, mb: 2 }}>
            {product?.quantity !== undefined && (
              <Typography variant="body2">
                <strong>Quantity in Stock:</strong> {product.quantity}
              </Typography>
            )}
            {product?.categoryId?.categoryName && (
              <Typography variant="body2">
                <strong>Category:</strong> {product.categoryId.categoryName}
              </Typography>
            )}
          </Box>

          <Box sx={{ flexGrow: 1 }} />
          <Divider sx={{ mt: 2, mb: 2 }} />

          {/* Like count */}
          {likeCount > 0 && (
            <Typography variant="body2" sx={{ mb: 1, color: red[400], fontWeight: 600 }}>
              ❤️ {likeCount} {likeCount === 1 ? "person likes" : "people like"} this
            </Typography>
          )}

          {/* Action Buttons */}
          <Box sx={{ display: "flex", gap: 2, alignItems: "center" }}>

            <Button
              variant="contained"
              size="large"
              sx={{ flex: 1, borderRadius: 2, textTransform: "none", fontWeight: 600, fontSize: 16 }}
            >
              Add to Cart
            </Button>

            {/* ❤️ Like Button */}
            <Tooltip title={liked ? "Unlike" : "Add to Wishlist"}>
              <IconButton
                onClick={handleLike}
                sx={{
                  border: liked ? `1.5px solid ${red[400]}` : "1px solid #e0e0e0",
                  borderRadius: 2,
                  bgcolor: liked ? red[50] : "transparent",
                  transition: "all 0.2s",
                  "&:hover": { bgcolor: red[50] },
                }}
              >
                {liked
                  ? <FavoriteIcon sx={{ color: red[500] }} />
                  : <FavoriteBorderIcon />
                }
              </IconButton>
            </Tooltip>

            {/* 📤 Share Button */}
            <Tooltip title="Share this product">
              <IconButton
                onClick={handleShare}
                sx={{
                  border: "1px solid #e0e0e0",
                  borderRadius: 2,
                  transition: "all 0.2s",
                  "&:hover": { bgcolor: "#e3f2fd", border: "1.5px solid #1976d2" },
                }}
              >
                <ShareIcon sx={{ color: "#1976d2" }} />
              </IconButton>
            </Tooltip>

          </Box>
        </Box>
      </Box>

      {/* Snackbar */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={2500}
        onClose={handleSnackbarClose}
        anchorOrigin={{ vertical: "bottom", horizontal: "center" }}
      >
        <Alert onClose={handleSnackbarClose} severity={snackbar.severity} sx={{ width: "100%" }}>
          {snackbar.message}
        </Alert>
      </Snackbar>

    </Box>
  );
}
